head.b:skin:
/* <Variable name="page.background" description="Page background" type="color" default="#fbf5f1" value="#fbf5f1"/><Variable name="page.text" description="Text color" type="color" default="#533c41" value="#533c41"/><Variable name="theme.accent" description="Accent color" type="color" default="#975763" value="#975763"/> */
/* Blogger stylesheet compatibility: restore the spacing Blogger's own widget stylesheet removes, and keep post content inside a phone screen. */
h1{margin:.67em 0}h2{margin:.83em 0}h3{margin:1em 0}h4{margin:1.33em 0}h1,h2,h3,h4,a img{position:static}body{padding:0;word-break:normal}.post-body{width:auto;overflow-x:auto}.post-body a[style*='margin-left'],.post-body a[style*='margin-right']{margin-inline:0!important}.post-body .separator,.post-body .tr-caption-container{max-width:100%}.widget .post-body ul,.widget .post-body ol{margin:1em 0;padding:0 0 0 1.4em;line-height:inherit}.widget .post-body li{margin:0 0 .35em;padding:0}.latest-empty{display:none}.single-view{font-size:1rem}.single-view .post-title{overflow-wrap:anywhere}
:root{--bg:$(page.background);--ink:$(page.text);--accent:$(theme.accent);--heading:'Cormorant Garamond', Georgia, serif;--body:Arial, sans-serif}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 var(--body)}h1,h2,h3{font-family:var(--heading);line-height:1.15}a{color:inherit;text-underline-offset:4px}a:hover{text-decoration-thickness:2px}img{max-width:100%;height:auto}svg{max-width:100%;height:auto}button,input{font:inherit}a:focus-visible,button:focus-visible,summary:focus-visible,input:focus-visible{outline:3px solid currentColor;outline-offset:5px}a,button,summary{touch-action:manipulation}nav{max-width:100%}p,h1,h2,h3,a{overflow-wrap:anywhere}.skip-link{position:fixed;top:-100px;left:16px;z-index:100;background:var(--ink);color:var(--bg);padding:12px}.skip-link:focus{top:12px}.section,.widget{min-width:0;margin:0;padding:0;line-height:inherit}.latest{max-width:1200px;margin:64px auto;padding:0 24px}.posts-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}.post-card{min-width:0}.post-title a{text-decoration:none}.post-title a:hover{text-decoration:underline}.post-media{display:block;aspect-ratio:16/10;overflow:hidden;background:color-mix(in srgb,var(--accent) 12%,var(--bg))}.post-media img{width:100%;height:100%;object-fit:cover}.post-art{height:100%;display:grid;place-items:center;font:italic 70px var(--heading);color:var(--accent)}.post-meta{margin-top:18px;font-size:12px}.post-meta a{margin-right:12px}.pager{display:flex;justify-content:space-between;gap:20px;margin-top:40px;padding-top:20px;border-top:1px solid currentColor}.pager a{padding:10px 0}.post-body{max-width:70ch;margin-inline:auto;overflow-wrap:anywhere}.post-body img,.post-body iframe{max-width:100%}.post-body pre,.post-body table{display:block;overflow:auto;max-width:100%}.single-view .latest{max-width:900px}.single-view .section-heading{display:none}.single-view .post-title{font-size:clamp(32px,5vw,62px)}.single-view #comments{margin-top:60px}.empty-state,.error-state{padding:45px 0}.error-state{max-width:900px;margin:auto;padding:70px 24px}.listing-heading{font-size:clamp(28px,5vw,52px)}#Attribution1,.widget.Attribution{display:none!important}@media(max-width:700px){.posts-grid{grid-template-columns:1fr}.latest{margin:45px auto}.pager{flex-wrap:wrap}}
.vv-head{margin:0 6vw;padding:30px 0;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #d9c5c7}.vv-head>a{font:30px 'Cormorant Garamond', Georgia,serif;text-decoration:none}.vv-head nav{display:flex;gap:30px;font-size:12px}.vv-invitation{text-align:center;padding:65px 20px 90px;position:relative;max-width:1000px;margin:auto}.vv-small{font-size:10px;letter-spacing:2.5px}.vv-invitation h1{font-size:clamp(44px,5.7vw,82px);line-height:1.13;font-weight:400;margin:30px 0}.vv-invitation em,.vv-planning em{color:#975763}.vv-invitation>p:not(.vv-small){font-size:14px;line-height:1.9}.vv-florals{max-width:620px;margin:0 auto}.vv-florals svg{width:100%;display:block}.vv-seal{background:#975763;color:#fff;border-radius:50%;height:120px;width:120px;display:grid;place-content:center;font-size:12px;line-height:1.7;text-decoration:none;margin:-28px auto 0;position:relative;transition:transform .3s}.vv-seal i{font-family:'Cormorant Garamond', Georgia,serif;font-size:15px}.vv-seal:hover,.vv-seal:focus-visible{transform:rotate(-7deg)}.vv-planning{background:#ede2dc;padding:75px 9vw;display:grid;grid-template-columns:1fr 1.2fr;gap:90px}.vv-planning h2{font-size:62px;font-weight:400;line-height:1.1;margin:25px 0}.vv-planning p{font-size:14px;line-height:1.8;max-width:330px}.vv-planning ol{padding:0;list-style:none}.vv-planning li{display:flex;gap:26px;padding:20px 0;border-bottom:1px solid #d1b8bb}.vv-planning li>span{font:italic 28px 'Cormorant Garamond', Georgia,serif;color:#975763}.vv-planning h3{font:24px 'Cormorant Garamond', Georgia,serif;margin:0}.vv-planning li a{font-size:11px}.latest{max-width:1200px;padding:30px 6vw!important}.section-heading{text-align:center;font:38px 'Cormorant Garamond', Georgia,serif;margin-bottom:45px}.post-media{display:none!important}.post-card{padding:28px;border:1px solid #d9c5c7;border-radius:100px 100px 0 0;text-align:center;padding-top:50px}.post-title{font:25px 'Cormorant Garamond', Georgia,serif;line-height:1.25}.post-meta{font-size:10px;text-transform:uppercase;letter-spacing:1px}.post-excerpt{font-size:13px;line-height:1.8}.vv-values{text-align:center;padding:65px 20px 90px;background:#f2e6e5}.vv-values>span{font-size:48px;color:#975763}.vv-values>p{font-size:12px;line-height:1.9}.vv-values h2{font-size:clamp(40px,5vw,65px);font-weight:400;line-height:1.15;margin:25px}.vv-values a{font-size:12px;display:inline-block;margin-top:18px}.vv-foot{text-align:center;padding:45px 20px}.vv-foot>a:first-child{font:28px 'Cormorant Garamond', Georgia,serif;text-decoration:none}.vv-foot p{font-size:11px;margin:20px}.vv-foot>a:last-child{font-size:11px}@media(max-width:700px){.vv-head{flex-direction:column;gap:22px}.vv-head nav{gap:17px;flex-wrap:wrap;justify-content:center}.vv-invitation{padding-top:48px}.vv-planning{grid-template-columns:1fr;gap:15px;padding:50px 7vw}.vv-planning h2{font-size:48px}.vv-seal{width:100px;height:100px;margin-top:0}.post-card{border-radius:55px 55px 0 0}}
h1,h2,h3{font-family:'Cormorant Garamond', Georgia, serif}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto!important}*,*::before,*::after{animation:none!important;transition:none!important}.post-media img{transform:none!important}}@media print{nav,.skip-link,.pager{display:none!important}body{background:white;color:black}}
